-- Runtime MCP read-only user for Runtime Test (production).
-- Generated by sinasaeedi/laravel-runtime-mcp. Review it, set a strong password, and run it as a user
-- that can create users and grant privileges. Re-run `php artisan runtime-mcp:doctor` afterwards.
-- MySQL and MariaDB have no CONNECT or schema USAGE grant: CREATE USER gives USAGE, which is no privilege.
-- Host '%' accepts a connection from any host. Narrow it if you can (runtime-mcp:install --host).
CREATE USER 'runtime_mcp_ro'@'%' IDENTIFIED BY 'CHANGE_ME';
GRANT SELECT ON `runtime_mcp`.`failed_jobs` TO 'runtime_mcp_ro'@'%';
GRANT SELECT ON `runtime_mcp`.`order_items` TO 'runtime_mcp_ro'@'%';
GRANT SELECT ON `runtime_mcp`.`orders` TO 'runtime_mcp_ro'@'%';
GRANT SELECT (`id`, `name`, `email`, `created_at`, `updated_at`) ON `runtime_mcp`.`users` TO 'runtime_mcp_ro'@'%';
-- No grant (denied_tables): `runtime_mcp`.`cache`, `runtime_mcp`.`jobs`, `runtime_mcp`.`password_reset_tokens`, `runtime_mcp`.`personal_access_tokens`, `runtime_mcp`.`sessions`
-- Masked columns (not granted): `runtime_mcp`.`users`.`password`, `runtime_mcp`.`users`.`remember_token`, `runtime_mcp`.`users`.`api_token`
-- New tables get NO grant automatically. Add a GRANT when you add a table.
